  ('5eed0003-0000-4000-8000-000000000022', 275000.00, 'Paid'),
  ('5eed0003-0000-4000-8000-000000000023', 950000.00, 'Paid'),
  ('5eed0003-0000-4000-8000-000000000024', 450000.00, 'Not Invoiced');

-- Sanity check: counts and roles as generated, or the whole load rolls back.
do $$
begin
  if (select count(*) from public.clients where id::text like '5eed0002-%') <> 21
    or (select count(*) from public.engagements where id::text like '5eed0003-%') <> 23
    or (select count(*) from public.engagement_financials where engagement_id::text like '5eed0003-%') <> 23
  then
    raise exception 'Seed check failed: row counts differ from the generated data';
  end if;
  if exists (
    select 1 from (values ('5eed0001-0000-4000-8000-000000000001'::uuid, 'owner'::public.app_role, false), ('5eed0001-0000-4000-8000-000000000002'::uuid, 'owner'::public.app_role, false), ('5eed0001-0000-4000-8000-000000000011'::uuid, 'consultant'::public.app_role, false), ('5eed0001-0000-4000-8000-000000000012'::uuid, 'consultant'::public.app_role, true), ('5eed0001-0000-4000-8000-000000000021'::uuid, 'marketing'::public.app_role, false)) as v(id, role, can_see_values)
    left join public.profiles p on p.id = v.id
    where p.id is null or p.role is distinct from v.role
      or p.can_see_values is distinct from v.can_see_values or not p.active
  ) then
    raise exception 'Seed check failed: a demo profile is missing or has the wrong role';
  end if;
end
$$;
